# --- Policy: maximum total retained size ---------------------------------
# Delete the oldest non-protected, still-retained artifacts (ties broken by
# Name) until the retained total fits under the cap. Protected artifacts are
# never sacrificed; if they alone exceed the cap we record a warning.
if ($null -ne $MaxTotalSizeBytes) {
    $retainedSize = [long](($items | Where-Object Action -eq 'Retain' | Measure-Object -Property SizeBytes -Sum).Sum)

    if ($retainedSize -gt $MaxTotalSizeBytes) {
        # Candidates eligible to be sacrificed, oldest first.
        $candidates = @($items |
            Where-Object { $_.Action -eq 'Retain' -and -not $_.Protected } |
            Sort-Object -Property @{Expression='CreatedAt';Descending=$false}, @{Expression='Name';Descending=$false})

        foreach ($item in $candidates) {
            if ($retainedSize -le $MaxTotalSizeBytes) { break }
            $item.Action = 'Delete'
            $item.Reason = "Deleted: max total size cap of $MaxTotalSizeBytes bytes exceeded (oldest-first eviction)"
            $retainedSize -= $item.SizeBytes
        }

        if ($retainedSize -gt $MaxTotalSizeBytes) {
            $warnings.Add("Retained size $retainedSize bytes still exceeds the max total size cap of $MaxTotalSizeBytes bytes; remaining artifacts are protected by keep-latest-$KeepLatestPerWorkflow and cannot be deleted.")
        }
    }
}

