    SpaceReclaimedBytes = [long](($deleted  | Measure-Object -Property SizeBytes -Sum).Sum)
    RetainedSizeBytes   = [long](($retained | Measure-Object -Property SizeBytes -Sum).Sum)
    Warnings            = @($warnings)
}

