        SizeBytes     = [long]$a.SizeBytes
        CreatedAt     = [datetime]$a.CreatedAt
        WorkflowRunId = $a.WorkflowRunId
        Action        = 'Retain'
        Reason        = 'Retained: satisfies every enabled retention policy'
    }
