            $plan.Summary.DeletedCount | Should -Be 0
        }

        It 'never deletes keep-latest-N protected artifacts to satisfy the cap and warns instead' {
            # Two protected artifacts already exceed the cap; nothing can be deleted.
            $artifacts = @(
                New-TestArtifact -Name 'p1' -WorkflowRunId 1 -SizeBytes 500 -CreatedAt $script:RefDate.AddDays(-1)
