- name: Generate artifact deletion plan
  shell: pwsh
  run: |
    Write-Host "Scenario file: $env:CLEANUP_SCENARIO_PATH"

    # Manual execute mode overrides the scenario's dryRun; otherwise the
    # scenario file decides (dry-run by default).
    if ('${{ github.event.inputs.execute }}' -eq 'true') {
      $report = ./Invoke-ArtifactCleanupCli.ps1 -Execute 2>&1 | Out-String
    }
    else {
      $report = ./Invoke-ArtifactCleanupCli.ps1 2>&1 | Out-String
    }
    $code = $LASTEXITCODE

    # Echo the plan to the build log (this is what the act harness parses).
    Write-Output $report

    # Publish the same plan to the GitHub job summary.
    if ($env:GITHUB_STEP_SUMMARY) {
      '## Artifact cleanup plan' | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append -Encoding utf8
      '```text'                  | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append -Encoding utf8
      $report                    | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append -Encoding utf8
      '```'                      | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append -Encoding utf8
    }

    if ($code -ne 0) { throw "Cleanup CLI exited with code $code." }

